#[public]
#[implements(ICapped)]
impl Capped {
    /// Constructor.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `cap` - The token supply cap.
    ///
    /// # Errors
    ///
